let audioContext;
const playSound=(kind='tap')=>{if(!S.settings.sounds)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioContext??=new C();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});const o=audioContext.createOscillator(),g=audioContext.createGain(),now=audioContext.currentTime;const key=typeof kind==='boolean'?(kind?'finish':'timeout'):kind;const settings={tap:[430,.035],start:[610,.10],tick:[880,.025],timeout:[170,.14],point:[760,.065],achievement:[1040,.13],turn:[530,.09],finish:[660,.13],win:[920,.16],tie:[510,.14]}[key]||[430,.035];o.type='sine';o.frequency.setValueAtTime(settings[0],now);g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(.035,now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+settings[1]);o.connect(g).connect(audioContext.destination);o.start(now);o.stop(now+settings[1]);}catch{}};
const nav=[['home','الرئيسية','home'],['units','الدروس والأسئلة','book'],['challenges','التحديات','zap'],['mistakes','مراجعة الأخطاء','refresh'],['stats','الإحصائيات','chart'],['achievements','الإنجازات','award'],['about','حول المنصة','info'],['settings','الإعدادات','settings']];
function levelFromXp(xp){return Math.floor(Math.sqrt((xp||0)/180))+1;}
function soloResults(){return S.results.filter(r=>r.mode!=='duel');}
function lessonMetrics(id){
 const items=soloResults().flatMap(r=>r.items||[]).filter(x=>S.byId.get(x.id)?.lesson_id===id);
 const attempted=items.filter(x=>x.response!==null&&x.response!==undefined), unique=new Set(attempted.map(x=>x.id)), right=new Set(attempted.filter(x=>x.correct).map(x=>x.id));
 const available=S.valid.filter(q=>q.lesson_id===id).length;
 return {answered:attempted.length,unique:unique.size,correct:attempted.filter(x=>x.correct).length,coverage:available?Math.round(unique.size/available*100):0,mastered:unique.size>=15&&right.size/unique.size>=.8};
}
function completedCount(){return allLessons().filter(l=>lessonMetrics(l.id).mastered).length;}
function statsTotals(){let total=0,correct=0,duration=0;for(const r of soloResults()){total+=r.answered||0;correct+=r.correct||0;duration+=r.duration||0;}return {total,correct,duration,accuracy:total?Math.round(correct/total*100):0};}
